import Darwin
import Foundation
import SwiftUI
import CGlassPrivateABI
import CGlassCompatibility
import SiriGlassModel

@_silgen_name("gw_subvariant")
private func gwSubvariant(_ name: String, _ source: UnsafeRawPointer, _ destination: UnsafeMutableRawPointer)

// Swift ABI entry generated by `glass_explicit.S`: x0 is the private 40-byte
// storage pointer and x8 is compiler-provided storage for the typed `Glass`.
@_silgen_name("siri_glass_init_public_from_private")
private func initializePublicGlass(from privateValue: UnsafeRawPointer) -> Glass

public enum PrivateGlassAdapterError: Error, LocalizedError {
    case incompatible(String)
    case compose(String)

    public var errorDescription: String? {
        switch self {
        case .incompatible(let detail): return "Private Glass adapter unavailable: \(detail)"
        case .compose(let detail): return "Private Glass composition failed: \(detail)"
        }
    }
}

/// Replaceable, fail-closed adapter for the derived local Glass ABI.
@MainActor public final class PrivateGlassAdapter {
    public static let shared = PrivateGlassAdapter()

    private let compatibilityError: String?

    public init() {
        compatibilityError = Self.checkCompatibility()
    }

    public func compose(_ parameters: GlassParameters) throws -> Glass {
        if let validationError = parameters.validationError() {
            throw PrivateGlassAdapterError.compose(validationError)
        }
        if let compatibilityError { throw PrivateGlassAdapterError.incompatible(compatibilityError) }

        // The comparison uses the public type directly. Never feed a public
        // Glass.regular value into private _Glass modifiers or its destructor.
        if parameters.kind == 5 { return .regular }

        if let audioMeters = parameters.audioMeters {
            guard var raw = glass_siri_base() else {
                throw PrivateGlassAdapterError.compose(Self.privateLastError())
            }
            do {
                // The array-meter reference call constructs its base and
                // optional subvariant before applying the audio options.
                try applyVariant(parameters.variant, to: &raw)

                guard MemoryLayout<[Float]>.size == MemoryLayout<UnsafeRawPointer?>.size,
                      let amplitudesStorage = Self.arrayStorage(audioMeters.normalizedPowerAmplitudes),
                      let frequenciesStorage = Self.arrayStorage(audioMeters.stopFrequenciesHz) else {
                    throw PrivateGlassAdapterError.incompatible("Swift Array<Float> storage representation is unavailable")
                }
                let meterGlass = withExtendedLifetime(audioMeters) {
                    glass_apply_audio_meters_wave(
                        UnsafeRawPointer(raw),
                        amplitudesStorage,
                        frequenciesStorage,
                        parameters.personality
                    )
                }
                guard let next = meterGlass else {
                    throw PrivateGlassAdapterError.compose(Self.privateLastError())
                }
                glass_destroy(raw)
                raw = next

                // The captured array-meter path places the optional lense
                // after SiriWaveOptions, unlike the legacy dB comparison path.
                if parameters.kind == 3 {
                    guard let next = glass_apply_lense(UnsafeRawPointer(raw)) else {
                        throw PrivateGlassAdapterError.compose(Self.privateLastError())
                    }
                    glass_destroy(raw)
                    raw = next
                }
                try applyShadow(parameters.excludesShadow, to: &raw)
            } catch {
                glass_destroy(raw)
                throw error
            }
            return Self.consumeAsPublicGlass(raw)
        }

        guard var raw = glass_compose(parameters.kind, parameters.personality, parameters.audioPowerDB) else {
            throw PrivateGlassAdapterError.compose(Self.privateLastError())
        }
        do {
            // Preserve the old dB material ordering and only then set its
            // variant; array-meter ordering is handled above.
            try applyVariant(parameters.variant, to: &raw)
            try applyShadow(parameters.excludesShadow, to: &raw)
        } catch {
            glass_destroy(raw)
            throw error
        }
        return Self.consumeAsPublicGlass(raw)
    }

    private func applyVariant(_ variant: String?, to raw: inout UnsafeMutableRawPointer) throws {
        guard let variant, !variant.isEmpty else { return }
        guard let destination = glass_alloc() else {
            throw PrivateGlassAdapterError.compose(Self.privateLastError())
        }
        gwSubvariant(variant, UnsafeRawPointer(raw), destination)
        glass_destroy(raw)
        raw = destination
    }

    private func applyShadow(_ excludesShadow: Bool?, to raw: inout UnsafeMutableRawPointer) throws {
        guard let excludesShadow else { return }
        guard let destination = glass_excluding_shadow(UnsafeRawPointer(raw), excludesShadow ? 1 : 0) else {
            throw PrivateGlassAdapterError.compose(Self.privateLastError())
        }
        // The C wrapper returns a distinct live private value; retire the
        // previous one before transferring the final value to public Glass.
        glass_destroy(raw)
        raw = destination
    }

    private static func arrayStorage(_ values: [Float]) -> UnsafeRawPointer? {
        withUnsafePointer(to: values) { arrayPointer in
            UnsafeRawPointer(arrayPointer).load(as: UnsafeRawPointer?.self)
        }
    }

    private static func checkCompatibility() -> String? {
        #if arch(arm64)
        #else
        return "the captured private ABI is supported only on arm64"
        #endif

        let os = ProcessInfo.processInfo.operatingSystemVersion
        let version = "\(os.majorVersion).\(os.minorVersion).\(os.patchVersion)"
        guard version == "27.0.1" else { return "tested macOS version is 27.0.1; running \(version)" }

        var buildBuffer = [CChar](repeating: 0, count: 128)
        var buildLength = buildBuffer.count
        let buildResult = buildBuffer.withUnsafeMutableBufferPointer { buffer in
            sysctlbyname("kern.osversion", buffer.baseAddress, &buildLength, nil, 0)
        }
        guard buildResult == 0 else { return "cannot read kern.osversion for private ABI compatibility" }
        let build = String(cString: buildBuffer)
        guard build == "26A434" else { return "tested macOS build is 26A434; running \(build)" }

        var systemSize: UInt64 = 0
        var systemStride: UInt64 = 0
        var errorBuffer = [CChar](repeating: 0, count: 512)
        let compatible = errorBuffer.withUnsafeMutableBufferPointer { error in
            SiriGlassCheckPrivateCompatibility(
                UInt64(MemoryLayout<Glass>.size),
                UInt64(MemoryLayout<Glass>.stride),
                &systemSize,
                &systemStride,
                error.baseAddress,
                Int32(error.count)
            )
        }
        guard compatible == 1 else {
            let detail = errorBuffer.first == 0 ? "required SwiftUICore symbol or Glass metadata check failed" : String(cString: errorBuffer)
            return detail
        }
        guard MemoryLayout<Glass>.size == Int(systemSize), MemoryLayout<Glass>.stride == Int(systemStride) else {
            return "SwiftUI.Glass layout differs from private metadata: Swift \(MemoryLayout<Glass>.size)/\(MemoryLayout<Glass>.stride), metadata \(systemSize)/\(systemStride)"
        }
        return nil
    }

    private static func privateLastError() -> String {
        guard let pointer = glass_last_error() else { return "compose returned null without an error message" }
        return String(cString: pointer)
    }

    private static func consumeAsPublicGlass(_ raw: UnsafeMutableRawPointer) -> Glass {
        // The explicit initializer constructs an actual public `Glass` value
        // from private `_Glass` storage. On the gated ABI it reads the 40-byte
        // input and initializes the typed result; ownership moves to that result.
        // Free only this consumed backing allocation: calling glass_destroy
        // here would destroy the transferred private value a second time.
        let value = initializePublicGlass(from: UnsafeRawPointer(raw))
        free(raw)
        return value
    }
}
